CREATE TYPE "PhysicalDonationKind" AS ENUM ('GOODS', 'CASH', 'MIXED');
CREATE TYPE "PhysicalDonationStatus" AS ENUM ('DRAFT', 'AWAITING_DONOR_CONFIRMATION', 'CONFIRMED', 'REJECTED', 'INSPECTION', 'ACCEPTED', 'DECLINED', 'DEPOSIT_PENDING', 'DEPOSIT_MATCHED', 'RECONCILED');
CREATE TYPE "PhysicalDonationLineType" AS ENUM ('GOODS', 'CASH');
CREATE TYPE "PhysicalLineInspectionStatus" AS ENUM ('PENDING', 'ACCEPTED', 'PARTIALLY_ACCEPTED', 'REJECTED');
CREATE TYPE "InspectionDecision" AS ENUM ('ACCEPTED', 'PARTIALLY_ACCEPTED', 'DECLINED');
CREATE TYPE "PhysicalCashDepositStatus" AS ENUM ('PENDING', 'MATCHED', 'REJECTED');
CREATE TABLE "physical_donations" ("id" UUID NOT NULL, "clerkUserId" UUID NOT NULL, "donorProfileId" UUID, "donorName" TEXT NOT NULL, "donorPhoneEncrypted" TEXT NOT NULL, "donorPhoneHash" TEXT NOT NULL, "donorPhoneLast4" TEXT NOT NULL, "kind" "PhysicalDonationKind" NOT NULL, "status" "PhysicalDonationStatus" NOT NULL DEFAULT 'DRAFT', "submissionVersion" INTEGER NOT NULL DEFAULT 1, "submittedAt" TIMESTAMP(3), "confirmedAt" TIMESTAMP(3), "rejectedAt" TIMESTAMP(3), "inspectedAt" TIMESTAMP(3), "finalizedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "physical_donations_pkey" PRIMARY KEY ("id"));
CREATE TABLE "physical_donation_lines" ("id" UUID NOT NULL, "physicalDonationId" UUID NOT NULL, "lineType" "PhysicalDonationLineType" NOT NULL, "itemName" TEXT NOT NULL, "category" TEXT, "quantity" INTEGER NOT NULL, "unit" TEXT NOT NULL, "declaredValue" DECIMAL(18,2), "acceptedQuantity" INTEGER, "approvedUnitValue" DECIMAL(18,2), "inspectionStatus" "PhysicalLineInspectionStatus" NOT NULL DEFAULT 'PENDING', "rejectionReason" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "physical_donation_lines_pkey" PRIMARY KEY ("id"));
CREATE TABLE "physical_donation_inspections" ("id" UUID NOT NULL, "physicalDonationId" UUID NOT NULL, "inspectorUserId" UUID NOT NULL, "decision" "InspectionDecision" NOT NULL, "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "physical_donation_inspections_pkey" PRIMARY KEY ("id"));
CREATE TABLE "physical_cash_deposits" ("id" UUID NOT NULL, "physicalDonationId" UUID NOT NULL, "amount" DECIMAL(18,2) NOT NULL, "depositReference" TEXT NOT NULL, "status" "PhysicalCashDepositStatus" NOT NULL DEFAULT 'PENDING', "recordedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "matchedAt" TIMESTAMP(3), CONSTRAINT "physical_cash_deposits_pkey" PRIMARY KEY ("id"));
CREATE INDEX "physical_donations_clerkUserId_createdAt_idx" ON "physical_donations"("clerkUserId", "createdAt");
CREATE INDEX "physical_donations_donorPhoneHash_createdAt_idx" ON "physical_donations"("donorPhoneHash", "createdAt");
CREATE INDEX "physical_donations_status_createdAt_idx" ON "physical_donations"("status", "createdAt");
CREATE INDEX "physical_donation_lines_physicalDonationId_idx" ON "physical_donation_lines"("physicalDonationId");
CREATE INDEX "physical_donation_inspections_physicalDonationId_createdAt_idx" ON "physical_donation_inspections"("physicalDonationId", "createdAt");
CREATE INDEX "physical_donation_inspections_inspectorUserId_createdAt_idx" ON "physical_donation_inspections"("inspectorUserId", "createdAt");
CREATE UNIQUE INDEX "physical_cash_deposits_depositReference_key" ON "physical_cash_deposits"("depositReference");
CREATE INDEX "physical_cash_deposits_physicalDonationId_status_idx" ON "physical_cash_deposits"("physicalDonationId", "status");
ALTER TABLE "physical_donations" ADD CONSTRAINT "physical_donations_clerkUserId_fkey" FOREIGN KEY ("clerkUserId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "physical_donations" ADD CONSTRAINT "physical_donations_donorProfileId_fkey" FOREIGN KEY ("donorProfileId") REFERENCES "donor_profiles"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "physical_donation_lines" ADD CONSTRAINT "physical_donation_lines_physicalDonationId_fkey" FOREIGN KEY ("physicalDonationId") REFERENCES "physical_donations"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "physical_donation_inspections" ADD CONSTRAINT "physical_donation_inspections_physicalDonationId_fkey" FOREIGN KEY ("physicalDonationId") REFERENCES "physical_donations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "physical_donation_inspections" ADD CONSTRAINT "physical_donation_inspections_inspectorUserId_fkey" FOREIGN KEY ("inspectorUserId") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "physical_cash_deposits" ADD CONSTRAINT "physical_cash_deposits_physicalDonationId_fkey" FOREIGN KEY ("physicalDonationId") REFERENCES "physical_donations"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
